import React, { useState } from "react";
import { Helmet } from "react-helmet";
import Icon from "components/AppIcon";
import PublicHeader from "../../components/ui/PublicHeader";
import Footer from "../../components/ui/Footer";

const PublicContact = () => {
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    subject: "",
    message: "",
    agreeToPrivacy: false
  });

  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState(null);
  const [submitMessage, setSubmitMessage] = useState("");

  const subjects = [
    { value: "", label: "Select a subject" },
    { value: "admission", label: "Admission Inquiry" },
    { value: "partnership", label: "Partnership Opportunity" },
    { value: "volunteer", label: "Volunteering" },
    { value: "general", label: "General Information" },
    { value: "feedback", label: "Feedback" },
    { value: "support", label: "Technical Support" }
  ];

  const validateForm = () => {
    const newErrors = {};
    
    if (!formData.firstName.trim()) newErrors.firstName = "First name is required";
    else if (formData.firstName.length > 50) newErrors.firstName = "First name cannot exceed 50 characters";
    
    if (!formData.lastName.trim()) newErrors.lastName = "Last name is required";
    else if (formData.lastName.length > 50) newErrors.lastName = "Last name cannot exceed 50 characters";
    
    if (!formData.email.trim()) newErrors.email = "Email is required";
    else if (!/^\w+([\.-]?\w+)*@\w+([\.-]?\w+)*(\.\w{2,3})+$/.test(formData.email)) {
      newErrors.email = "Please enter a valid email address";
    }
    
    if (formData.phone && !/^[\+]?[0-9\s\-\(\)]+$/.test(formData.phone)) {
      newErrors.phone = "Please enter a valid phone number";
    }
    
    if (!formData.subject) newErrors.subject = "Please select a subject";
    
    if (!formData.message.trim()) newErrors.message = "Message is required";
    else if (formData.message.length > 2000) newErrors.message = "Message cannot exceed 2000 characters";
    
    if (!formData.agreeToPrivacy) newErrors.agreeToPrivacy = "You must agree to the privacy policy";
    
    return newErrors;
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value
    }));
    
    // Clear error for this field when user starts typing
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: "" }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    const validationErrors = validateForm();
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }
    
    setIsSubmitting(true);
    setSubmitStatus(null);
    setSubmitMessage("");
    
    try {
      // Prepare data for API
      const submissionData = {
        firstname: formData.firstName.trim(),
        lastname: formData.lastName.trim(),
        email: formData.email.trim(),
        phone: formData.phone.trim() || undefined,
        subject: formData.subject,
        message: formData.message.trim()
      };
      
      const response = await fetch("https://new-school-web.onrender.com/contact/submit", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(submissionData)
      });
      
      const data = await response.json();
      
      if (response.ok) {
        setSubmitStatus("success");
        setSubmitMessage("Thank you for your message! We'll get back to you soon.");
        
        // Reset form
        setFormData({
          firstName: "",
          lastName: "",
          email: "",
          phone: "",
          subject: "",
          message: "",
          agreeToPrivacy: false
        });
        setErrors({});
      } else {
        setSubmitStatus("error");
        setSubmitMessage(data.message || "Failed to send message. Please try again.");
      }
    } catch (error) {
      console.error("Submission error:", error);
      setSubmitStatus("error");
      setSubmitMessage("Network error. Please check your connection and try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const contactInfo = [
    {
      icon: "fas fa-phone",
      title: "Phone",
      details: ["(+250) 786 003 991", "(+250) 788 123 456"],
      description: "Available Mon-Fri, 8am-5pm"
    },
    {
      icon: "fas fa-envelope",
      title: "Email",
      details: ["gsphuye@yahoo.fr", "info@gsdesparents.rw"],
      description: "We respond within 24 hours"
    },
    {
      icon: "fas fa-map-marker-alt",
      title: "Address",
      details: ["KK 521 St, Butare", "Southern Province, Rwanda"],
      description: "Main Campus"
    },
    {
      icon: "fas fa-clock",
      title: "Office Hours",
      details: ["Monday - Friday: 8am - 5pm", "Saturday: 9am - 1pm"],
      description: "Closed on Sundays"
    }
  ];

  return (
    <>
      <Helmet>
        <title>Contact Us | GS DES PARENTS</title>
        <meta
          name="description"
          content="Get in touch with GS DES PARENTS. Contact us for admissions, partnerships, volunteering opportunities, or general inquiries. We're here to help!"
        />
        <meta
          name="keywords"
          content="contact GS DES PARENTS, school contact, admissions inquiry, Rwanda education, Butare school, parent community"
        />
        <meta property="og:title" content="Contact Us - GS DES PARENTS" />
        <meta
          property="og:description"
          content="Reach out to GS DES PARENTS for inquiries, partnerships, or to join our community"
        />
        <meta property="og:type" content="website" />
        <link rel="canonical" href="/contact" />
      </Helmet>

      <div className="min-h-screen bg-background">
        <PublicHeader />

        <main className="pt-20">
          {/* Hero Section */}
          <section className="relative py-12 lg:py-20 bg-gradient-to-br from-primary/10 via-background to-secondary/10 overflow-hidden">
            <div className="absolute inset-0 bg-grid-pattern opacity-5"></div>
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
              <div className="text-center max-w-3xl mx-auto">
                <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-primary/10 mb-6">
                  <i className="fas fa-envelope-open-text text-2xl text-primary"></i>
                </div>
                <h1 className="text-4xl md:text-5xl font-bold text-gray-900 mb-4">
                  Get In Touch
                </h1>
                <p className="text-lg text-gray-600 mb-8">
                  We'd love to hear from you. Whether you have questions about admissions, 
                  want to partner with us, or simply want to say hello, reach out to us.
                </p>
                <div className="flex flex-wrap justify-center gap-4">
                  <div className="flex items-center text-gray-700">
                    <i className="fas fa-check-circle text-green-500 mr-2"></i>
                    <span>Quick Response</span>
                  </div>
                  <div className="flex items-center text-gray-700">
                    <i className="fas fa-check-circle text-green-500 mr-2"></i>
                    <span>24/7 Support</span>
                  </div>
                  <div className="flex items-center text-gray-700">
                    <i className="fas fa-check-circle text-green-500 mr-2"></i>
                    <span>Professional Team</span>
                  </div>
                </div>
              </div>
            </div>
          </section>

          {/* Contact Section */}
          <section className="py-12 lg:py-20 bg-white">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 lg:gap-16">
                {/* Contact Information */}
                <div className="space-y-8">
                  <div className="bg-gradient-to-br from-primary/5 to-secondary/5 rounded-2xl p-8">
                    <h2 className="text-2xl font-bold text-gray-900 mb-6">
                      Contact Information
                    </h2>
                    <p className="text-gray-600 mb-8">
                      Feel free to reach out to us through any of these channels. 
                      Our dedicated team is ready to assist you with any inquiries.
                    </p>
                    
                    <div className="space-y-6">
                      {contactInfo.map((info, index) => (
                        <div key={index} className="flex items-start">
                          <div className="flex-shrink-0 w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center mr-4">
                            <i className={`${info.icon} text-lg text-primary`}></i>
                          </div>
                          <div>
                            <h3 className="font-semibold text-gray-900 mb-1">{info.title}</h3>
                            {info.details.map((detail, idx) => (
                              <p key={idx} className="text-gray-700">{detail}</p>
                            ))}
                            <p className="text-sm text-gray-500 mt-1">{info.description}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                    
                    <div className="mt-8 pt-8 border-t border-gray-200">
                      <h3 className="font-semibold text-gray-900 mb-4">Follow Us</h3>
                      <div className="flex space-x-4">
                        {[
                          { icon: "Facebook", color: "bg-blue-600 text-white", label: "Facebook", link:"https://www.facebook.com/profile.php?id=61578792264434" },
                          { icon: "Instagram", color: "bg-pink-600", label: "Instagram" },
                          { icon: "Linkedin", color: "bg-blue-700", label: "LinkedIn", link:"https://www.linkedin.com/company/gsdesparents/" },
                          { icon: "Youtube", color: "bg-red-600", label: "YouTube" }
                        ].map((social, idx) => (
                          <a
                            key={idx}
                            href={social.link || "#"}
                            className={`${social.color} w-10 h-10 rounded-full flex items-center justify-center text-white hover:opacity-90 transition-opacity`}
                            aria-label={social.label}
                          >
                            <Icon name={social.icon}></Icon>
                          </a>
                        ))}
                      </div>
                    </div>
                  </div>

                  {/* Stats */}
                  <div className="grid grid-cols-2 gap-4">
                    {[
                      { number: "500+", label: "Active Members", icon: "fas fa-users" },
                      { number: "24h", label: "Avg Response Time", icon: "fas fa-clock" },
                      { number: "98%", label: "Satisfaction Rate", icon: "fas fa-star" },
                      { number: "15+", label: "Years Experience", icon: "fas fa-award" }
                    ].map((stat, idx) => (
                      <div key={idx} className="bg-gray-50 rounded-xl p-6 text-center">
                        <div className="text-3xl font-bold text-primary mb-2">{stat.number}</div>
                        <div className="flex items-center justify-center text-gray-600">
                          <i className={`${stat.icon} mr-2 text-sm`}></i>
                          <span className="text-sm">{stat.label}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Contact Form */}
                <div className="bg-white rounded-2xl shadow-xl border border-gray-100 p-8">
                  <div className="mb-8">
                    <h2 className="text-2xl font-bold text-gray-900 mb-2">Send us a Message</h2>
                    <p className="text-gray-600">
                      Fill out the form below and we'll get back to you as soon as possible.
                    </p>
                  </div>

                  {submitStatus && (
                    <div className={`mb-6 p-4 rounded-lg ${submitStatus === "success" ? "bg-green-50 border border-green-200" : "bg-red-50 border border-red-200"}`}>
                      <div className="flex items-center">
                        <i className={`fas ${submitStatus === "success" ? "fa-check-circle text-green-500" : "fa-exclamation-circle text-red-500"} mr-3`}></i>
                        <p className={`${submitStatus === "success" ? "text-green-800" : "text-red-800"}`}>
                          {submitMessage}
                        </p>
                      </div>
                    </div>
                  )}

                  <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <div>
                        <label htmlFor="firstName" className="block text-sm font-medium text-gray-700 mb-2">
                          First Name *
                        </label>
                        <div className="relative">
                          <input
                            type="text"
                            id="firstName"
                            name="firstName"
                            value={formData.firstName}
                            onChange={handleChange}
                            className={`w-full px-4 py-3 rounded-lg border ${errors.firstName ? "border-red-300 focus:ring-red-500 focus:border-red-500" : "border-gray-300 focus:ring-primary focus:border-primary"} focus:ring-2 focus:ring-opacity-50 focus:outline-none transition-colors`}
                            placeholder="John"
                          />
                          <div className="absolute right-3 top-3">
                            <i className="fas fa-user text-gray-400"></i>
                          </div>
                        </div>
                        {errors.firstName && (
                          <p className="mt-2 text-sm text-red-600 flex items-center">
                            <i className="fas fa-exclamation-circle mr-1"></i> {errors.firstName}
                          </p>
                        )}
                      </div>

                      <div>
                        <label htmlFor="lastName" className="block text-sm font-medium text-gray-700 mb-2">
                          Last Name *
                        </label>
                        <div className="relative">
                          <input
                            type="text"
                            id="lastName"
                            name="lastName"
                            value={formData.lastName}
                            onChange={handleChange}
                            className={`w-full px-4 py-3 rounded-lg border ${errors.lastName ? "border-red-300 focus:ring-red-500 focus:border-red-500" : "border-gray-300 focus:ring-primary focus:border-primary"} focus:ring-2 focus:ring-opacity-50 focus:outline-none transition-colors`}
                            placeholder="Doe"
                          />
                          <div className="absolute right-3 top-3">
                            <i className="fas fa-user text-gray-400"></i>
                          </div>
                        </div>
                        {errors.lastName && (
                          <p className="mt-2 text-sm text-red-600 flex items-center">
                            <i className="fas fa-exclamation-circle mr-1"></i> {errors.lastName}
                          </p>
                        )}
                      </div>
                    </div>

                    <div>
                      <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-2">
                        Email Address *
                      </label>
                      <div className="relative">
                        <input
                          type="email"
                          id="email"
                          name="email"
                          value={formData.email}
                          onChange={handleChange}
                          className={`w-full px-4 py-3 rounded-lg border ${errors.email ? "border-red-300 focus:ring-red-500 focus:border-red-500" : "border-gray-300 focus:ring-primary focus:border-primary"} focus:ring-2 focus:ring-opacity-50 focus:outline-none transition-colors`}
                          placeholder="john.doe@example.com"
                        />
                        <div className="absolute right-3 top-3">
                          <i className="fas fa-envelope text-gray-400"></i>
                        </div>
                      </div>
                      {errors.email && (
                        <p className="mt-2 text-sm text-red-600 flex items-center">
                          <i className="fas fa-exclamation-circle mr-1"></i> {errors.email}
                        </p>
                      )}
                    </div>

                    <div>
                      <label htmlFor="phone" className="block text-sm font-medium text-gray-700 mb-2">
                        Phone Number
                      </label>
                      <div className="relative">
                        <input
                          type="tel"
                          id="phone"
                          name="phone"
                          value={formData.phone}
                          onChange={handleChange}
                          className={`w-full px-4 py-3 rounded-lg border ${errors.phone ? "border-red-300 focus:ring-red-500 focus:border-red-500" : "border-gray-300 focus:ring-primary focus:border-primary"} focus:ring-2 focus:ring-opacity-50 focus:outline-none transition-colors`}
                          placeholder="+250 78X XXX XXX"
                        />
                        <div className="absolute right-3 top-3">
                          <i className="fas fa-phone text-gray-400"></i>
                        </div>
                      </div>
                      {errors.phone && (
                        <p className="mt-2 text-sm text-red-600 flex items-center">
                          <i className="fas fa-exclamation-circle mr-1"></i> {errors.phone}
                        </p>
                      )}
                    </div>

                    <div>
                      <label htmlFor="subject" className="block text-sm font-medium text-gray-700 mb-2">
                        Subject *
                      </label>
                      <div className="relative">
                        <select
                          id="subject"
                          name="subject"
                          value={formData.subject}
                          onChange={handleChange}
                          className={`w-full px-4 py-3 rounded-lg border appearance-none ${errors.subject ? "border-red-300 focus:ring-red-500 focus:border-red-500" : "border-gray-300 focus:ring-primary focus:border-primary"} focus:ring-2 focus:ring-opacity-50 focus:outline-none transition-colors bg-white`}
                        >
                          {subjects.map((option, index) => (
                            <option key={index} value={option.value}>
                              {option.label}
                            </option>
                          ))}
                        </select>
                        <div className="absolute right-3 top-3 pointer-events-none">
                          <i className="fas fa-chevron-down text-gray-400"></i>
                        </div>
                      </div>
                      {errors.subject && (
                        <p className="mt-2 text-sm text-red-600 flex items-center">
                          <i className="fas fa-exclamation-circle mr-1"></i> {errors.subject}
                        </p>
                      )}
                    </div>

                    <div>
                      <label htmlFor="message" className="block text-sm font-medium text-gray-700 mb-2">
                        Message *
                      </label>
                      <div className="relative">
                        <textarea
                          id="message"
                          name="message"
                          value={formData.message}
                          onChange={handleChange}
                          rows="6"
                          className={`w-full px-4 py-3 rounded-lg border ${errors.message ? "border-red-300 focus:ring-red-500 focus:border-red-500" : "border-gray-300 focus:ring-primary focus:border-primary"} focus:ring-2 focus:ring-opacity-50 focus:outline-none transition-colors resize-none`}
                          placeholder="Please describe your inquiry in detail..."
                        />
                        <div className="absolute right-3 top-3">
                          <i className="fas fa-edit text-gray-400"></i>
                        </div>
                      </div>
                      {errors.message && (
                        <p className="mt-2 text-sm text-red-600 flex items-center">
                          <i className="fas fa-exclamation-circle mr-1"></i> {errors.message}
                        </p>
                      )}
                      <div className="mt-2 text-right text-sm text-gray-500">
                        {formData.message.length}/2000 characters
                      </div>
                    </div>

                    <div className="flex items-start">
                      <div className="flex items-center h-5">
                        <input
                          id="agreeToPrivacy"
                          name="agreeToPrivacy"
                          type="checkbox"
                          checked={formData.agreeToPrivacy}
                          onChange={handleChange}
                          className="h-4 w-4 text-primary focus:ring-primary border-gray-300 rounded"
                        />
                      </div>
                      <div className="ml-3">
                        <label htmlFor="agreeToPrivacy" className="text-sm text-gray-700">
                          I agree to the{" "}
                          <a href="/privacy-policy" className="text-primary hover:underline font-medium">
                            privacy policy
                          </a>{" "}
                          and consent to having my data processed. *
                        </label>
                        {errors.agreeToPrivacy && (
                          <p className="mt-1 text-sm text-red-600 flex items-center">
                            <i className="fas fa-exclamation-circle mr-1"></i> {errors.agreeToPrivacy}
                          </p>
                        )}
                      </div>
                    </div>

                    <button
                      type="submit"
                      disabled={isSubmitting}
                      className={`w-full py-4 px-6 rounded-lg font-medium text-white transition-all duration-300 ${isSubmitting ? "bg-primary/70 cursor-not-allowed" : "bg-primary hover:bg-primary/90 hover:shadow-lg"} flex items-center justify-center`}
                    >
                      {isSubmitting ? (
                        <>
                          <i className="fas fa-spinner fa-spin mr-2"></i>
                          Sending...
                        </>
                      ) : (
                        <>
                          <i className="fas fa-paper-plane mr-2"></i>
                          Send Message
                        </>
                      )}
                    </button>

                    <p className="text-center text-sm text-gray-500 mt-4">
                      We typically respond within 1-2 business days
                    </p>
                  </form>
                </div>
              </div>
            </div>
          </section>

          {/* Map Section */}
          <section className="py-12 lg:py-20 bg-gray-50">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
              <div className="text-center mb-12">
                <h2 className="text-3xl font-bold text-gray-900 mb-4">Find Us Here</h2>
                <p className="text-lg text-gray-600 max-w-2xl mx-auto">
                  Visit our campus in Butare. We're located in a convenient and accessible area.
                </p>
              </div>
              
              <div className="rounded-2xl overflow-hidden shadow-xl border border-gray-200">
                <iframe
                  src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d4421.679827929996!2d29.747805210979074!3d-2.590967697376191!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x19c30cfb97000001%3A0xf0b8a4f71069ec82!2sEcole%20Secondaire%20Des%20Parent%20De%20Butare!5e1!3m2!1sen!2srw!4v1740497545315!5m2!1sen!2srw"
                  width="100%"
                  height="500"
                  style={{ border: 0 }}
                  allowFullScreen=""
                  loading="lazy"
                  referrerPolicy="no-referrer-when-downgrade"
                  title="GS Des Parents Butare Location"
                  className="w-full h-[500px]"
                ></iframe>
              </div>
 
            </div>
          </section>

          {/* CTA Section */}
          <section className="py-12 lg:py-20 bg-gradient-to-r from-primary to-secondary">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
              <div className="text-center text-white">
                <h2 className="text-3xl md:text-4xl font-bold mb-6">Join Our Community Today</h2>
                <p className="text-xl mb-8 max-w-3xl mx-auto opacity-90">
                  Be part of a vibrant community dedicated to excellence in education and community development.
                </p>
                <div className="flex flex-col sm:flex-row gap-4 justify-center">
                  <a
                    href="/admissions"
                    className="bg-white text-primary hover:bg-gray-100 font-semibold py-3 px-8 rounded-lg transition-colors duration-300 inline-flex items-center justify-center"
                  >
                    <i className="fas fa-graduation-cap mr-2"></i> Apply Now
                  </a>
                  <a
                    href="/visit"
                    className="bg-transparent border-2 border-white text-white hover:bg-white/10 font-semibold py-3 px-8 rounded-lg transition-colors duration-300 inline-flex items-center justify-center"
                  >
                    <i className="fas fa-calendar-alt mr-2"></i> Schedule a Visit
                  </a>
                </div>
              </div>
            </div>
          </section>
        </main>

        <Footer />
      </div>
    </>
  );
};

export default PublicContact;