import React, { useState, useMemo } from "react";
import { Helmet } from "react-helmet";
import PublicHeader from "../../components/ui/PublicHeader";
import BreadcrumbNavigation from "../../components/ui/BreadcrumbNavigation";
import HeroSection from "./components/HeroSection";
import Sidebar from "./components/Sidebar";
import BlogGrid from "./components/BlogGrid";
import Pagination from "./components/Pagination";
import Footer from "../../components/ui/Footer";

// Mock blog data
const mockBlogPosts = [
  {
    id: 1,
    title: "Mathematics",
    publishedDate: "2025-01-10",
    category: "Youth Empowerment",
    tags: ["Software Development", "L3", "General Modeles"],
    featuredImage: "/public/assets/images/no_image.png",
    slug: "mathematics book for L3SOD",
  },
];

const LibraryContent = () => {
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [currentPage, setCurrentPage] = useState(1);
  const postsPerPage = 4;

  // Get unique categories
  const categories = useMemo(() => {
    const cats = [
      "All",
      ...new Set(mockBlogPosts?.map((post) => post?.category)),
    ];
    return cats;
  }, []);

  // Get popular tags
  const popularTags = useMemo(() => {
    const allTags = mockBlogPosts?.flatMap((post) => post?.tags || []);
    const tagCounts = allTags?.reduce((acc, tag) => {
      acc[tag] = (acc?.[tag] || 0) + 1;
      return acc;
    }, {});
    return Object.entries(tagCounts)
      ?.sort(([, a], [, b]) => b - a)
      ?.slice(0, 8)
      ?.map(([tag, count]) => ({ tag, count }));
  }, []);

  // Filter posts based on search and category
  const filteredPosts = useMemo(() => {
    return mockBlogPosts?.filter((post) => {
      const matchesSearch =
        !searchQuery ||
        post?.title?.toLowerCase()?.includes(searchQuery?.toLowerCase()) ||
        post?.tags?.some((tag) =>
          tag?.toLowerCase()?.includes(searchQuery?.toLowerCase())
        );

      const matchesCategory =
        selectedCategory === "All" || post?.category === selectedCategory;

      return matchesSearch && matchesCategory;
    });
  }, [searchQuery, selectedCategory]);

  // Paginate posts
  const paginatedPosts = useMemo(() => {
    const startIndex = (currentPage - 1) * postsPerPage;
    return filteredPosts?.slice(startIndex, startIndex + postsPerPage);
  }, [filteredPosts, currentPage, postsPerPage]);

  const totalPages = Math.ceil(filteredPosts?.length / postsPerPage);

  // Get recent posts for sidebar
  const recentPosts = useMemo(() => {
    return mockBlogPosts
      ?.sort((a, b) => new Date(b?.publishedDate) - new Date(a?.publishedDate))
      ?.slice(0, 3);
  }, []);

  return (
    <>
      <Helmet>
        <title>Libary - GS DES PARENTS </title>
        <meta
          name="description"
          content="Read inspiring stories, insights, and updates from GS DES PARENTS community members. Explore articles on youth empowerment, technology, leadership, and community development."
        />
        <meta
          name="keywords"
          content="GS DES PARENTS, CEFOTEC, GSPHUYE, blog, community stories, youth empowerment, Rwanda development, community insights"
        />
        <meta property="og:title" content="Blog - GS DES PARENTS" />
        <meta
          property="og:description"
          content="Inspiring stories and insights from the GS DES PARENTS community"
        />
        <meta property="og:type" content="website" />
        <link rel="canonical" href="/blog-listing" />
      </Helmet>

      <div className="min-h-screen bg-background">
        <PublicHeader />

        <main className="pt-16">
          {/* Breadcrumb Navigation */}
          <div className="bg-muted/30 py-4">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <BreadcrumbNavigation />
            </div>
          </div>

          {/* Hero Section */}
          <HeroSection
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
          />

           {/* Main Content */}
          <section className="py-12">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <div className="lg:grid lg:grid-cols-12 lg:gap-8">
                {/* Main Blog Grid */}
                <div className="lg:col-span-8">
                  <BlogGrid
                    posts={paginatedPosts}
                    totalPosts={filteredPosts?.length}
                    searchQuery={searchQuery}
                    selectedCategory={selectedCategory}
                  />

                  {/* Pagination */}
                  {totalPages > 1 && (
                    <Pagination
                      currentPage={currentPage}
                      totalPages={totalPages}
                      onPageChange={setCurrentPage}
                    />
                  )}
                </div>

                {/* Sidebar */}
                <div className="lg:col-span-4 mt-12 lg:mt-0">
                  <Sidebar
                    categories={categories}
                    selectedCategory={selectedCategory}
                    onCategoryChange={setSelectedCategory}
                    popularTags={popularTags}
                    recentPosts={recentPosts}
                    onTagClick={setSearchQuery}
                  />
                </div>
              </div>
            </div>
          </section>
        </main>

        {/* Footer */}
        <Footer />
      </div>
    </>
  );
};

export default LibraryContent;
