import React from "react";

const DocumentViewer = ({ url, name, onClose }) => {
  // Only render if url is provided
  if (!url) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-70">
      <div className="relative w-full max-w-4xl h-[80vh] bg-white rounded-lg shadow-lg flex flex-col">
        <button
          onClick={onClose}
          className="absolute top-2 right-2 bg-gray-200 hover:bg-gray-300 rounded-full p-2 text-gray-700"
          aria-label="Close document viewer"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            className="w-6 h-6"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M6 18L18 6M6 6l12 12"
            />
          </svg>
        </button>
        <div className="flex-1 overflow-auto p-4">
          <iframe
            src={url}
            title={name}
            className="w-full h-full min-h-[60vh] border-none rounded"
            frameBorder="0"
            allowFullScreen
          />
        </div>
        <div className="p-4 border-t text-center text-sm text-gray-600">
          {name}
        </div>
      </div>
    </div>
  );
};

export default DocumentViewer;
