import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import Icon from '../AppIcon';

const BreadcrumbNavigation = ({ customBreadcrumbs = null }) => {
  const location = useLocation();

  // Route mapping for breadcrumb labels
  const routeLabels = {
    'public-homepage': 'Home',
    'about-us': 'About Us',
    'user-login': 'Sign In',
    'member-dashboard': 'Dashboard',
    'profile-management': 'Profile',
    'admin-panel': 'Admin Panel',
    'blog-posts': 'Blog Posts',
    'events': 'Events',
    'announcements': 'Announcements',
    'resources': 'Resources',
    'members': 'Members',
    'member-requests': 'Member Requests',
    'roles': 'Roles & Permissions',
    'settings': 'Settings',
    'general': 'General',
    'email': 'Email Templates',
    'integrations': 'Integrations',
  };

  // Generate breadcrumbs from current path
  const generateBreadcrumbs = () => {
    if (customBreadcrumbs) {
      return customBreadcrumbs;
    }

    const pathSegments = location?.pathname?.split('/')?.filter(segment => segment !== '');
    const breadcrumbs = [];

    // Build breadcrumb path
    let currentPath = '';
    pathSegments?.forEach((segment, index) => {
      currentPath += `/${segment}`;
      const label = routeLabels?.[segment] || segment?.charAt(0)?.toUpperCase() + segment?.slice(1);
      
      breadcrumbs?.push({
        label,
        path: currentPath,
        isLast: index === pathSegments?.length - 1
      });
    });

    return breadcrumbs;
  };

  const breadcrumbs = generateBreadcrumbs();

  // Don't show breadcrumbs for root paths or single-level paths
  if (breadcrumbs?.length <= 1) {
    return null;
  }

  return (
    <nav className="flex items-center space-x-2 text-sm font-body mb-6" aria-label="Breadcrumb">
      <ol className="flex items-center space-x-2">
        {breadcrumbs?.map((breadcrumb, index) => (
          <li key={breadcrumb?.path} className="flex items-center space-x-2">
            {index > 0 && (
              <Icon 
                name="ChevronRight" 
                size={16} 
                className="text-muted-foreground" 
                aria-hidden="true"
              />
            )}
            
            {breadcrumb?.isLast ? (
              <span 
                className="text-foreground font-medium"
                aria-current="page"
              >
                {breadcrumb?.label}
              </span>
            ) : (
              <Link
                to={breadcrumb?.path}
                className="text-muted-foreground hover:text-primary transition-smooth hover:underline"
              >
                {breadcrumb?.label}
              </Link>
            )}
          </li>
        ))}
      </ol>
    </nav>
  );
};

export default BreadcrumbNavigation;