import React, { useState, useEffect } from 'react';
import Image from '../../../components/AppImage';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Skeleton from '../../../components/ui/Skeleton';
import Alert from '../../../components/ui/Alert';

const EventsSection = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState('All');

  // Extract unique categories for filtering
  const categories = ['All', ...new Set(events.map(event => event.category))];

  useEffect(() => {
    fetchEvents();
  }, []);

  const fetchEvents = async () => {
    try {
      setLoading(true);
      setError(null);
      
      // Use the correct endpoint for events
      // Common endpoints for REST APIs:
      // 1. GET /api/events - Get all events
      // 2. GET /events - Get all events
      // 3. GET /api/events/all - Get all events
      
      const response = await fetch('https://new-school-web.onrender.com/api/events');
      
      // If that doesn't work, try these other common patterns:
      // const response = await fetch('http://localhost:8000/events');
      // const response = await fetch('http://localhost:8000/api/events/all');
      // const response = await fetch('http://localhost:8000/events/all');
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const data = await response.json();
      
      console.log('API Response data:', data);
      
      // Handle different API response structures
      let eventsData = [];
      
      if (Array.isArray(data)) {
        // If response is directly an array
        eventsData = data;
      } else if (data.data && Array.isArray(data.data)) {
        // If response has { data: [...] }
        eventsData = data.data;
      } else if (data.events && Array.isArray(data.events)) {
        // If response has { events: [...] }
        eventsData = data.events;
      } else if (data.result && Array.isArray(data.result)) {
        // If response has { result: [...] }
        eventsData = data.result;
      } else {
        console.error('Unexpected API response structure:', data);
        throw new Error('Unexpected API response structure');
      }
      
      // Filter only active events and sort by date (upcoming first)
      const activeEvents = eventsData
        .filter(event => event.isActive !== false) // Include events where isActive is true or undefined
        .sort((a, b) => new Date(a.date) - new Date(b.date));
      
      console.log('Processed active events:', activeEvents);
      setEvents(activeEvents);
      
    } catch (err) {
      console.error('Error fetching events:', err);
      setError(`Failed to load events. Error: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('en-GB', {
        weekday: 'long',
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      });
    } catch (error) {
      return 'Date not available';
    }
  };

  const formatTime = (timeString) => {
    try {
      if (!timeString) return 'Time not available';
      
      // Handle both "HH:MM" and "HH:MM:SS" formats
      const [hours, minutes] = timeString.split(':');
      const time = new Date();
      time.setHours(parseInt(hours), parseInt(minutes || 0));
      return time.toLocaleTimeString('en-GB', {
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
      });
    } catch (error) {
      return 'Time not available';
    }
  };

  const getAttendancePercentage = (attendees, maxAttendees) => {
    if (!maxAttendees || maxAttendees === 0) return 0;
    return Math.round((attendees / maxAttendees) * 100);
  };

  const getDayOfMonth = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.getDate();
    } catch (error) {
      return '--';
    }
  };

  const getMonthShort = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('en-GB', { month: 'short' });
    } catch (error) {
      return '---';
    }
  };

  const getAttendanceStatus = (percentage) => {
    if (percentage >= 90) return 'Almost Full';
    if (percentage >= 75) return 'Filling Fast';
    if (percentage >= 50) return 'Good Availability';
    return 'Available';
  };

  const getAttendanceColor = (percentage) => {
    if (percentage >= 90) return 'bg-red-500';
    if (percentage >= 75) return 'bg-orange-500';
    return 'bg-primary';
  };

  const filteredEvents = selectedCategory === 'All' 
    ? events 
    : events.filter(event => event.category === selectedCategory);

  // Loading skeleton
  if (loading) {
    return (
      <section className="py-16 lg:py-24 bg-muted/30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12">
            <Skeleton className="h-10 w-64 mx-auto mb-4" />
            <Skeleton className="h-6 w-96 mx-auto" />
          </div>
          <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-8">
            {[1, 2, 3].map((i) => (
              <Skeleton key={i} className="h-[500px] rounded-lg" />
            ))}
          </div>
        </div>
      </section>
    );
  }

  return (
    <section className="py-16 lg:py-24 bg-gradient-to-b from-background to-muted/10">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header */}
        <div className="text-center mb-12">
          <div className="inline-flex items-center justify-center mb-4">
            <div className="w-12 h-1 bg-primary rounded-full mr-4"></div>
            <span className="text-primary font-semibold uppercase tracking-wider text-sm">
              Community Events
            </span>
            <div className="w-12 h-1 bg-primary rounded-full ml-4"></div>
          </div>
          
          <h2 className="font-heading font-bold text-3xl lg:text-4xl text-foreground mb-4">
            Upcoming <span className="text-primary">Events</span>
          </h2>
          
          <p className="font-body text-lg text-muted-foreground max-w-2xl mx-auto mb-8">
            Join our community events and be part of meaningful conversations that drive positive change.
          </p>
          
          {/* Category Filter - Only show if there are events */}
          {events.length > 0 && (
            <div className="flex flex-wrap justify-center gap-2 mb-6">
              {categories.map((category) => (
                <Button
                  key={category}
                  variant={selectedCategory === category ? "default" : "outline"}
                  size="sm"
                  onClick={() => setSelectedCategory(category)}
                  className="rounded-full px-4"
                >
                  {category}
                </Button>
              ))}
            </div>
          )}
        </div>

        {/* Error Display */}
        {error && (
          <div className="mb-8">
            <Alert variant="destructive">
              <Icon name="AlertCircle" className="mr-2" />
              {error}
              <Button 
                variant="ghost" 
                size="sm" 
                onClick={fetchEvents}
                className="ml-4"
              >
                <Icon name="RefreshCw" size={16} className="mr-1" />
                Retry
              </Button>
            </Alert>
          </div>
        )}

        {/* Events Grid */}
        {filteredEvents.length > 0 ? (
          <>
            <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6 mb-12">
              {filteredEvents.map((event) => (
                <div 
                  key={event.id || event._id}
                  className="group bg-card rounded-xl shadow-lg hover:shadow-xl transition-all duration-300 overflow-hidden border border-border hover:border-primary/20 hover:-translate-y-1"
                >
                  {/* Image Container */}
                  <div className="relative overflow-hidden h-48 bg-gradient-to-br from-muted to-muted/50">
                    <Image
                      src={event.image}
                      alt={event.title}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                      fallbackSrc="/assets/event-placeholder.jpg"
                    />
                    
                    {/* Category Badge */}
                    <div className="absolute top-4 left-4">
                      <span className="bg-primary text-primary-foreground px-3 py-1 rounded-full text-xs font-semibold shadow-md">
                        {event.category}
                      </span>
                    </div>
                    
                    {/* Date Badge */}
                    <div className="absolute top-4 right-4 bg-card/95 backdrop-blur-sm rounded-lg p-3 text-center shadow-lg">
                      <div className="font-heading font-bold text-xl text-primary">
                        {getDayOfMonth(event.date)}
                      </div>
                      <div className="font-body text-xs text-muted-foreground uppercase tracking-wider">
                        {getMonthShort(event.date)}
                      </div>
                    </div>
                    
                    {/* Gradient Overlay */}
                    <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                  </div>

                  {/* Content */}
                  <div className="p-6">
                    <h3 className="font-heading font-bold text-xl text-foreground mb-3 line-clamp-2">
                      {event.title}
                    </h3>

                    <p className="font-body text-muted-foreground mb-4 line-clamp-2 text-sm leading-relaxed">
                      {event.description}
                    </p>

                    {/* Event Details */}
                    <div className="space-y-3 mb-4">
                      <div className="flex items-center text-sm">
                        <Icon name="Calendar" size={16} className="mr-3 text-primary flex-shrink-0" />
                        <span className="text-foreground">{formatDate(event.date)}</span>
                      </div>
                      <div className="flex items-center text-sm">
                        <Icon name="Clock" size={16} className="mr-3 text-primary flex-shrink-0" />
                        <span className="text-foreground">{formatTime(event.time)}</span>
                      </div>
                      <div className="flex items-center text-sm">
                        <Icon name="MapPin" size={16} className="mr-3 text-primary flex-shrink-0" />
                        <span className="text-foreground">{event.location}</span>
                      </div>
                    </div>

                    {/* Attendance Progress */}
                    <div className="mb-6">
                      <div className="flex justify-between items-center mb-2">
                        <span className="text-sm font-semibold text-foreground">
                          {getAttendanceStatus(getAttendancePercentage(event.attendees, event.maxAttendees))}
                        </span>
                        <span className="text-sm font-medium text-muted-foreground">
                          {event.attendees} of {event.maxAttendees} spots
                        </span>
                      </div>
                      <div className="flex items-center space-x-3">
                        <div className="flex-1 bg-muted rounded-full h-2 overflow-hidden">
                          <div 
                            className={`h-2 rounded-full transition-all duration-500 ${getAttendanceColor(getAttendancePercentage(event.attendees, event.maxAttendees))}`}
                            style={{ width: `${getAttendancePercentage(event.attendees, event.maxAttendees)}%` }}
                          ></div>
                        </div>
                        <span className="text-sm font-bold text-primary min-w-12">
                          {getAttendancePercentage(event.attendees, event.maxAttendees)}%
                        </span>
                      </div>
                    </div>

                    {/* Action Buttons */}
                    <div className="flex gap-3">
                      <Button 
                        variant="default" 
                        size="sm" 
                        className="flex-1 font-semibold"
                        iconName="Calendar"
                        iconPosition="left"
                        iconSize={16}
                        disabled={event.attendees >= event.maxAttendees}
                      >
                        {event.attendees >= event.maxAttendees ? 'Fully Booked' : 'Register Now'}
                      </Button>
                      <Button 
                        variant="outline" 
                        size="sm"
                        iconName="Info"
                        iconSize={16}
                        className="px-3"
                        title="More details"
                      />
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* View All Button */}
            <div className="text-center">
              <Button 
                variant="outline" 
                size="lg"
                iconName="Calendar"
                iconPosition="left"
                className="rounded-full px-8 border-primary/30 hover:border-primary"
              >
                View All Events
              </Button>
            </div>
          </>
        ) : (
          // No events state
          <div className="text-center py-12">
            <div className="inline-flex items-center justify-center w-16 h-16 bg-muted rounded-full mb-4">
              <Icon name="Calendar" size={32} className="text-muted-foreground" />
            </div>
            <h3 className="font-heading font-semibold text-xl text-foreground mb-2">
              {events.length > 0 ? 'No Events in Selected Category' : 'No Upcoming Events'}
            </h3>
            <p className="text-muted-foreground mb-6 max-w-md mx-auto">
              {events.length > 0 
                ? 'There are no events in the selected category. Try choosing a different category.'
                : 'There are no events scheduled at the moment. Please check back later for updates.'}
            </p>
            {events.length > 0 && (
              <Button 
                variant="outline"
                onClick={() => setSelectedCategory('All')}
                className="mr-2"
              >
                Show All Categories
              </Button>
            )}
            <Button 
              variant="default" 
              onClick={fetchEvents}
              iconName="RefreshCw"
              iconPosition="left"
            >
              Refresh Events
            </Button>
          </div>
        )}
      </div>
    </section>
  );
};

export default EventsSection;