import React from 'react';
import { Link } from 'react-router-dom';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import AppImage from '../../../components/AppImage';

const BlogCard = ({ post }) => {
  const handleShare = (platform) => {
    const url = `${window?.location?.origin}/library-view?slug=${post?.slug}`;
    const title = post?.title;
    
    const shareUrls = {
      twitter: `https://twitter.com/intent/tweet?text=${encodeURIComponent(title)}&url=${encodeURIComponent(url)}`,
      facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`,
      linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}`
    };
    
    if (shareUrls?.[platform]) {
      window?.open(shareUrls?.[platform], '_blank', 'width=600,height=400');
    }
  };

  return (
    <article className="bg-card rounded-lg border border-border shadow-card hover:shadow-elevated transition-smooth hover-lift group">
      {/* Featured Image */}
      <div className="aspect-video bg-muted rounded-t-lg overflow-hidden">
        <AppImage
          src={post?.featuredImage}
          alt={post?.title}
          className="w-full h-full object-cover group-hover:scale-105 transition-smooth duration-300"
        />
      </div>

      {/* Content */}
      <div className="p-6">
        {/* Category & Reading Time */}
        <div className="flex items-center justify-between mb-3">
          <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-primary/10 text-primary">
            {post?.category}
          </span>
          <div className="flex items-center text-muted-foreground text-sm">
            <Icon name="Calendar" size={14} className="mr-1" />
            {post?.publishedDate}
          </div>
        </div>

        {/* Title */}
        <h2 className="font-heading font-bold text-xl text-foreground mb-3 line-clamp-2 group-hover:text-primary transition-smooth">
          {post?.title}
        </h2>

        {/* Tags */}
        <div className="flex flex-wrap gap-2 mb-4">
          {post?.tags?.slice(0, 3)?.map((tag, index) => (
            <span 
              key={index}
              className="inline-flex items-center px-2 py-1 rounded text-xs font-medium bg-muted text-muted-foreground hover:bg-muted/80 transition-smooth cursor-pointer"
            >
              #{tag}
            </span>
          ))}
        </div>

        {/* Read More Link */}
        <div className="mt-4">
          <Link 
            to={`/blog-post-view?slug=${post?.slug}`}
            className="inline-flex items-center text-primary hover:text-primary/80 font-body font-medium text-sm transition-smooth"
          >
            <Button>
              <Icon name="Download" size={16} className="ml-1 group-hover:translate-x-1 transition-smooth me-3" />
              Overview 
            </Button> 
          </Link>
        </div>
      </div>
    </article>
  );
};

const BlogGrid = ({ posts, totalPosts, searchQuery, selectedCategory }) => {
  if (!posts || posts?.length === 0) {
    return (
      <div className="text-center py-12">
        <div className="w-20 h-20 bg-muted rounded-full flex items-center justify-center mx-auto mb-4">
          <Icon name="FileText" size={32} className="text-muted-foreground" />
        </div>
        <h3 className="font-heading font-bold text-xl text-foreground mb-2">
          No articles found
        </h3>
        <p className="font-body text-muted-foreground mb-6">
          {searchQuery || selectedCategory !== 'All' 
            ? "Try adjusting your search or filter criteria." :"Check back later for new content."}
        </p>
        <Button 
          variant="outline" 
          onClick={() => window?.location?.reload()}
        >
          Refresh Page
        </Button>
      </div>
    );
  }

  return (
    <div>
      {/* Results Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between mb-8">
        <div>
          <h2 className="font-heading font-bold text-2xl text-foreground mb-2">
            {searchQuery ? `Search Results` : 
             selectedCategory !== 'All' ? `${selectedCategory} Articles` : 'Latest Articles'}
          </h2>
          <p className="font-body text-muted-foreground">
            {searchQuery && (
              <span>Showing results for "{searchQuery}" • </span>
            )}
            {totalPosts} {totalPosts === 1 ? 'article' : 'articles'} found
          </p>
        </div>
        
        {/* Sort Options */}
        <div className="mt-4 sm:mt-0">
          <select className="px-3 py-2 border border-input bg-card rounded-lg font-body text-sm focus:ring-2 focus:ring-ring focus:border-transparent transition-smooth">
            <option value="newest">Newest First</option>
            <option value="oldest">Oldest First</option>
            <option value="popular">Most Popular</option>
          </select>
        </div>
      </div>

      {/* Blog Cards Grid */}
      <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2">
        {posts?.map((post) => (
          <BlogCard key={post?.id} post={post} />
        ))}
      </div>
    </div>
  );
};

export default BlogGrid;